/* ---------- Nebensätze: weil, dass, wenn ---------- */
K.add('de-a2-05', {
  lesson: [
    { p: "Türkçede yan cümle zaten fiille biter: *hasta **olduğum için** evde kalıyorum*. Almancada da benzer bir kural var: **weil, dass, wenn** gibi bir bağlaçtan sonra **çekimli fiil cümlenin en sonuna** gider. Hatalar çoğunlukla, alıştığın “fiil 2. sırada” düzeninin yan cümlede de kullanılmasından çıkar. Yan cümle ana cümleden her zaman **virgülle** ayrılır." },
    { table: { head: ["Bağlaç", "Anlamı", "Örnek"], rows: [
      ["weil", "çünkü, -diği için", "Ich bleibe zu Hause, **weil** ich krank **bin**."],
      ["dass", "-diğini, -ceğini (ki)", "Ich glaube, **dass** er heute nicht **kommt**."],
      ["wenn", "eğer; her -dığında", "**Wenn** es regnet, bleiben wir zu Hause."]
    ] } },
    { h: "1) Fiilin yeri: en sonda" },
    { p: "Ana cümlede çekimli fiil 2. sıradadır, yan cümlede **en sonda**:" },
    { table: { head: ["Fiil türü", "Ana cümle", "Yan cümle"], rows: [
      ["basit fiil", "Ich **bin** müde.", "…, weil ich müde **bin**."],
      ["ayrılabilen fiil", "Ich **stehe** früh **auf**.", "…, weil ich früh **aufstehe**."],
      ["modal fiil", "Ich **muss** früh aufstehen.", "…, weil ich früh aufstehen **muss**."],
      ["Perfekt", "Ich **habe** gearbeitet.", "…, weil ich gearbeitet **habe**."]
    ] } },
    { tip: "Ayrılabilen fiiller yan cümlede **birleşir** (*aufstehe, anrufe*). Modal fiil varsa **modal fiil** en sonda durur, mastar onun önündedir: *aufstehen **muss***. Perfekt’te çekimli olan **haben / sein** en sondadır: *gearbeitet **habe**, gekommen **bin***." },
    { warn: "En sık hata: *weil ich bin müde* ✗ → *weil ich müde **bin*** ✓. Ayrıca **dass** (bağlaç, iki **s**) ile **das** (artikel / “bu”) aynı okunur ama farklı yazılır: *Ich glaube, **dass** er kommt.*" },
    { h: "2) Yan cümle başta ise: ana cümlede fiil hemen gelir" },
    { p: "Yan cümle cümlenin başına geçince **tamamı 1. yer** sayılır. Ana cümlede **fiil hemen arkasından** (2. sıra) ve **özne ondan sonra** gelir: *Wenn es regnet, **bleiben wir** zu Hause.* ✓ (*Wenn es regnet, wir bleiben zu Hause* ✗). Yan cümle sonda olursa sıra normaldir: *Wir bleiben zu Hause, wenn es regnet.*" },
    { h: "3) weil mı, denn mi?" },
    { p: "İkisi de “çünkü” demektir. **weil** → yan cümle, fiil **sonda**: *…, weil ich krank **bin**.* **denn** → ana cümle gibi, fiil **yerinde**: *…, denn ich **bin** krank.* İkisini karıştırmamak için kural: **weil** gördüğünde fiili sona gönder." },
    { h: "4) wenn, wann ve als" },
    { p: "**wenn** = “eğer” (koşul) ve “her … -dığında” (tekrar eden durum): *Wenn ich Zeit habe, rufe ich an.* **wann** = “ne zaman?” (soru sözcüğü): *Wann kommst du?* Geçmişteki **tek bir olay** için kullanılan **als** B1’de gelecek; şimdilik bu işte *wenn*’i bilmen yeter." },
    { ex: [
      ["Ich lerne Deutsch, weil ich hier arbeiten möchte.", "Burada çalışmak istediğim için Almanca öğreniyorum."],
      ["Ich weiß, dass du morgen früh aufstehen musst.", "Yarın erken kalkman gerektiğini biliyorum."],
      ["Wenn du Hunger hast, koche ich Nudeln.", "Acıkırsan makarna pişiririm."],
      ["Sie ist müde, weil sie gestern lange gearbeitet hat.", "Dün uzun çalıştığı için yorgun."],
      ["Ich hoffe, dass wir am Samstag Zeit haben.", "Cumartesi günü vaktimiz olmasını umuyorum."]
    ] }
  ],
  exercises: [
    { id: "de-a2-05.1", t: "gap", q: "Ich lerne Deutsch, weil ich in Köln ___. (wohnen)", a: ["wohne"],
      wrong: { "wohnen": "Fiil yan cümlede de **çekilir**: özne *ich* → ich **wohne**. Mastar sadece modal fiilin yanında kalır.", "wohnt": "*wohnt* er/sie/es ve ihr içindir; *ich* ile **wohne**." },
      e: "*weil* → çekimli fiil sona: *…, weil ich in Köln **wohne***." },
    { id: "de-a2-05.2", t: "gap", q: "Ich bin müde, weil ich jeden Tag früh ___. (aufstehen)", a: ["aufstehe"],
      wrong: { "stehe auf": "Ayrılabilen fiil yan cümlede **ayrılmaz**, birleşir: *weil ich früh **aufstehe***.", "aufstehen": "Fiil özneye göre çekilir: ich **aufstehe**. Mastar hâli yanlış.", "stehe": "*auf* eksik. Yan cümlede ön ek fiille birleşir: **aufstehe**." },
      e: "Ana cümlede *Ich stehe auf*, yan cümlede **…, weil ich aufstehe**: ayrılabilen fiil birleşir ve sona gider." },
    { id: "de-a2-05.3", t: "gap", q: "Ich komme nicht, weil ich arbeiten ___. (müssen)", a: ["muss"],
      wrong: { "müssen": "Özne *ich* → ich **muss**. *müssen* wir/sie içindir.", "musst": "*musst* du içindir; ich → **muss**." },
      e: "Modal fiil yan cümlede **en sonda** durur, mastar (*arbeiten*) onun önünde: *weil ich arbeiten **muss***." },
    { id: "de-a2-05.4", t: "gap", q: "Ich glaube, ___ er heute nicht kommt.", a: ["dass"],
      wrong: { "das": "*das* artikel veya “bu” demektir (*Das ist gut.*). “… -diğini” için bağlaç **dass** gerekir (iki **s**).", "weil": "*weil* = çünkü; “inanıyorum çünkü” anlam bozar. *glauben*’dan sonra içerik **dass** ile bağlanır.", "wenn": "*wenn* = eğer. “Eğer gelmiyorsa” demek istemiyorsun; “gelmediğini” → **dass**." },
      e: "**dass** = “-diğini / ki”. *glauben, wissen, hoffen, sagen* gibi fiillerden sonra içerik yan cümle olarak gelir." },
    { id: "de-a2-05.5", t: "gap", q: "Rufen Sie mich an, ___ Sie Fragen haben.", a: ["wenn", "falls"],
      wrong: { "weil": "*weil* kesin bir sebebi bildirir (çünkü). “Sorunuz olursa” bir koşuldur: **wenn**.", "dass": "*dass* “-diğini” demektir; koşul için kullanılmaz." },
      e: "“Sorunuz olursa / varsa” = koşul → **wenn** (*falls* da aynı anlamda kabul edilir)." },
    { id: "de-a2-05.6", t: "gap", q: "Ich hoffe, dass du morgen Zeit ___. (haben)", a: ["hast"],
      wrong: { "hat": "*hat* er/sie/es içindir; *du* ile **hast**.", "haben": "*du* ile çekim: du **hast**. Mastar yan cümlede de çekilir." },
      e: "*dass* yan cümlesinde çekimli fiil sonda: *…, dass du morgen Zeit **hast***." },
    { id: "de-a2-05.7", t: "gap", q: "Wenn ich Zeit habe, ___ ich dich an. (anrufen)", a: ["rufe"],
      wrong: { "ich": "Yan cümle 1. yeri doldurur; ana cümlede **fiil hemen** gelir, özne sonra: *Wenn ich Zeit habe, **rufe** ich dich an.*", "anrufe": "Ana cümlede *anrufen* ayrılır: *rufe … an*. Birleşik hâl yan cümleye özgüdür." },
      e: "Yan cümle başta → ana cümlede **fiil + özne**: *Wenn ich Zeit habe, rufe ich dich an.*" },
    { id: "de-a2-05.8", t: "gap", q: "Ich bin müde, weil ich schlecht geschlafen ___. (haben / sein)", a: ["habe"],
      wrong: { "bin": "*schlafen* **haben** ile Perfekt kurar (yer değiştirme yok). *…, weil ich schlecht geschlafen **habe***.", "geschlafen": "Partizip metinde zaten var. Sona **çekimli** yardımcı fiil gelir: **habe**." },
      e: "Perfekt + *weil*: Partizip önde, **çekimli yardımcı fiil en sonda**: *geschlafen habe*." },
    { id: "de-a2-05.9", t: "mc", q: "“İşim olduğu için gelemiyorum.” Hangisi doğru?", o: ["Ich kann nicht kommen, weil ich arbeiten muss.", "Ich kann nicht kommen, weil ich muss arbeiten.", "Ich kann nicht kommen, weil muss ich arbeiten.", "Ich kann nicht kommen, weil ich arbeite muss."], a: 0,
      why: { 1: "*weil* yan cümle kurar; çekimli modal fiil **en sona** gitmeli: *arbeiten **muss***.", 2: "*weil*’den sonra fiil öne gelmez; özne önce, fiil **sonda**.", 3: "Mastar *arbeiten* olmalı; *arbeite* çekilmiş hâl modal fiilin yanında kullanılmaz." },
      e: "Modal fiil + mastar: *…, weil ich **arbeiten muss***. Çekimli olan modal fiil sonda." },
    { id: "de-a2-05.10", t: "mc", q: "“Bugün erken kalktığım için yorgunum.” Hangisi doğru?", o: ["Ich bin müde, weil ich heute früh aufgestanden bin.", "Ich bin müde, weil ich bin heute früh aufgestanden.", "Ich bin müde, weil ich heute früh bin aufgestanden.", "Ich bin müde, weil ich heute früh aufgestanden habe."], a: 0,
      why: { 1: "*weil* sonrası çekimli fiil **sona** gider; *bin* sonda olmalı.", 2: "Yardımcı fiil **Partizip’ten sonra**, cümlenin en sonunda durur: *aufgestanden **bin***.", 3: "*aufstehen* **sein** ile Perfekt kurar (yer/durum değişimi): *aufgestanden **bin***." },
      e: "Yan cümlede Perfekt: **Partizip + haben/sein**. *aufstehen → …, weil ich aufgestanden **bin***." },
    { id: "de-a2-05.11", t: "mc", q: "Hangi cümle **yanlış**?", o: ["Ich bleibe zu Hause, weil ich krank bin.", "Ich bleibe zu Hause, denn ich bin krank.", "Ich bleibe zu Hause, weil ich bin krank.", "Weil ich krank bin, bleibe ich zu Hause."], a: 2,
      why: { 0: "Doğru: *weil* → fiil sonda.", 1: "Doğru: *denn* ana cümle kurar, fiil yerinde (*ich bin*).", 3: "Doğru: yan cümle başta, ana cümlede fiil hemen gelir (*bleibe ich*)." },
      e: "*weil ich bin krank* ✗ → *weil ich krank **bin*** ✓. *weil* ile fiil sona, *denn* ile yerinde kalır." },
    { id: "de-a2-05.12", t: "order", q: "Cümleyi kur: “Hasta olduğum için evde kalıyorum.”", w: ["Ich", "bleibe", "zu Hause", "weil", "ich", "krank", "bin"], a: ["Ich bleibe zu Hause weil ich krank bin", "Weil ich krank bin bleibe ich zu Hause"],
      e: "Yan cümle sonda: *…, weil ich krank **bin***. Başa alırsan ana cümlede fiil hemen gelir: *Weil ich krank bin, **bleibe ich** zu Hause*. Virgül koymayı unutma." },
    { id: "de-a2-05.13", t: "order", q: "Cümleyi kur: “Yarın erken kalkması gerektiğini söylüyor.”", w: ["Er", "sagt", "dass", "er", "morgen früh", "aufstehen", "muss"], a: ["Er sagt dass er morgen früh aufstehen muss"],
      e: "*dass* yan cümlesinde modal fiil sonda: *aufstehen **muss***. Mastar modal fiilin hemen önünde." },
    { id: "de-a2-05.14", t: "order", q: "Cümleyi kur: “Vaktim olursa seni ararım.”", w: ["Wenn", "ich", "Zeit", "habe", "rufe", "ich", "dich", "an"], a: ["Wenn ich Zeit habe rufe ich dich an", "Ich rufe dich an wenn ich Zeit habe"],
      e: "Yan cümle başta: **Wenn ich Zeit habe** (fiil sonda) + ana cümlede **fiil + özne**: *rufe ich dich an*. Sonda olursa: *Ich rufe dich an, wenn ich Zeit habe.*" },
    { id: "de-a2-05.15", t: "match", q: "Bağlacı anlamıyla eşleştir:", p: [["weil", "çünkü (fiil sonda)"], ["denn", "çünkü (fiil yerinde)"], ["dass", "-diğini, ki"], ["wenn", "eğer, her -dığında"], ["wann", "ne zaman? (soru)"]],
      e: "**weil / denn** aynı anlam, farklı fiil yeri. **dass** içeriği bağlar, **wenn** koşul ya da tekrar, **wann** sorudur." },
    { id: "de-a2-05.16", t: "match", q: "Cümleleri tamamla:", p: [["Ich hoffe, dass", "du bald wieder gesund bist."], ["Ich habe Hunger, weil", "ich nichts gegessen habe."], ["Sie ist müde, weil", "sie schlecht geschlafen hat."], ["Ich rufe dich an, wenn", "ich zu Hause bin."], ["Wir kommen nicht, weil", "wir arbeiten müssen."]],
      e: "Her yan cümlede çekimli fiil sonda: *bist, habe, hat, bin, müssen*. Özne ve fiil uyumuna dikkat et: *du … bist*, *ich … habe / bin*, *sie … hat*, *wir … müssen*. Perfekt’te yardımcı fiil (*habe, hat*) en sondadır." },
    { id: "de-a2-05.17", t: "listen", say: "Ich komme später, weil ich noch arbeiten muss.", q: "Dinle. Ne anlama geliyor?", o: ["Daha sonra geleceğim, çünkü hâlâ çalışmam gerekiyor.", "Daha sonra geleceğim, çünkü işim bitti.", "Geç geldim, çünkü çalışmam gerekiyordu.", "Gelmeyeceğim, çünkü çalışmam gerekiyor."], a: 0,
      why: { 1: "*noch arbeiten muss* = hâlâ çalışması gerekiyor; işin bittiği söylenmiyor.", 2: "*komme* şimdiki/gelecek zamandır. Geçmiş için *bin … gekommen* duyardın.", 3: "*später kommen* = daha sonra gelmek; *nicht kommen* duymadın." },
      e: "*weil … arbeiten muss*: yan cümlede modal fiil **en sonda**. *noch* = hâlâ, *später* = daha sonra." },
    { id: "de-a2-05.18", t: "dictation", say: "Ich glaube, dass er heute nicht kommt.", a: ["Ich glaube, dass er heute nicht kommt."],
      wrong: { "Ich glaube, das er heute nicht kommt": "Bağlaç **dass** iki **s** ile yazılır; *das* artikel/“bu” demektir. İkisi aynı okunur, yazılışları farklı.", "Ich glaube, dass er heute kommt nicht": "Yan cümlede çekimli fiil **en sonda**: *nicht kommt*.", "Ich glaube, dass er kommt heute nicht": "*dass* yan cümlesinde fiil sonda: *heute nicht **kommt***." },
      e: "**dass** = bağlaç (iki s), fiil sonda: *…, dass er heute nicht **kommt***. Cümle başında virgül unutma." },
    { id: "de-a2-05.19", t: "speak", say: "Ich lerne Deutsch, weil ich hier arbeiten möchte.",
      e: "**weil** = “vayl” (w = v, ei = “ay”). **Deutsch** = “doyç”: **tsch** = ç. **möchte**: ö = Türkçe ö, ch = hafif nefes sesi, ç değil. **arbeiten**: r hafif, boğazdan. Virgülden sonra kısa dur." },
    { id: "de-a2-05.20", t: "speak", say: "Wenn es morgen regnet, bleibe ich zu Hause.",
      e: "**Wenn** = “ven” (w = v). **regnet**: g ve n’yi birbirine bağla; “reg-net”. Virgül yan cümlenin bittiği yerdir; ardından **bleibe ich**: fiil önde." },
    {"id":"de-a2-05.21","t":"cloze","q":"Bağlacı yaz.","text":"Er ist müde, {1} er nachts schlecht geschlafen hat. Ich hoffe, {2} es dir bald besser geht. {3} es morgen regnet, bleibe ich zu Hause.","gaps":{"1":{"a":["weil"],"o":["weil","dass","wenn"],"wrong":{"dass":"*dass* içerik cümlesi başlatır; neden için **weil**.","wenn":"*wenn* koşul/zaman içindir (… ise); burada gerçekleşmiş bir neden var: **weil**."}},"2":{"a":["dass"],"o":["dass","weil","ob"],"wrong":{"weil":"*hoffen* + **dass**; *weil* neden bildirir.","ob":"*ob* “mi” anlamında soru cümlesi içindir; *ich hoffe, dass …* kalıbı."}},"3":{"a":["Wenn","Falls"],"wrong":{"Weil":"*weil* kesin bir nedeni bildirir; yarın yağmur yağması henüz kesin değil, bir koşul: **Wenn**."}}},"e":"Yan cümlede (weil, dass, wenn) **fiil en sona** gider. Yan cümle başta ise ana cümlede fiil hemen gelir: *Wenn ich Zeit habe, **rufe** ich dich an.*"},
    {"id":"de-a2-05.22","t":"sort","q":"Fiil nerede?","cats":["Verb an 2. Stelle","Verb am Ende"],"items":[["weil",1],["denn",0],["dass",1],["wenn",1],["deshalb",0],["und",0]],"why":{"weil":"Yan cümle bağlacı → fiil sonda: *weil ich krank bin*.","denn":"Ana cümle bağlacı → fiil 2.: *denn ich bin krank*.","dass":"Yan cümle → fiil sonda: *dass er kommt*.","wenn":"Yan cümle → fiil sonda: *wenn es regnet*.","deshalb":"Zarf → fiil hemen arkasında (2. sırada): *deshalb bin ich …*.","und":"Ana cümle bağlacı → sıra değişmez, fiil 2."},"e":"Yan cümle bağlaçları (weil, dass, wenn, ob) **fiili sona** iter. Ana cümle bağlaçları (und, denn, aber, oder, sondern) fiilin yerini değiştirmez."},
    {"id":"de-a2-05.23","t":"speak","say":"Ich glaube, dass er heute kommt.","e":"**glaube**: **gl** birlikte, **au** = a-u (ağız a’dan u’ya kayar), “av” değil. **dass** = “das”, s sert ve kısa. **kommt**: o kısa, **mm** çift okunmaz, **t** sonda net."},
    {"id":"de-a2-05.24","t":"speak","say":"Wenn es regnet, bleibe ich zu Hause.","e":"**Wenn**: w = v, **nn** tek “n”. **regnet**: **g** ve **n** ayrı okunur: reeg-net. **Hause**: **au** = a+u kayması (“av” değil), **s** yumuşak “z”, sondaki e kısa (“havze” değil, “hauze”)."},
    { id: "de-a2-05.25", t: "respond", say: "Was machst du, wenn du frei hast? Warum gefällt dir das?",
      q: "Soruyu dinle ve 2–3 cümleyle cevap ver. wenn, weil, dass kullan.",
      chunks: ["Wenn ich frei habe, …","Das gefällt mir, weil …","Ich finde, dass …"],
      models: ["Wenn ich frei habe, spiele ich Gitarre. Das gefällt mir, weil es mich entspannt.","Wenn ich frei habe, gehe ich oft spazieren. Ich finde, dass mir die frische Luft guttut. Das gefällt mir, weil ich dann nicht an die Arbeit denke."],
      modelsN: ["Boş vaktim olduğunda gitar çalarım. Hoşuma gidiyor, çünkü beni rahatlatıyor.","Boş vaktim olduğunda sık sık yürüyüşe çıkarım. Bence temiz hava bana iyi geliyor. Hoşuma gidiyor, çünkü o zaman işi düşünmüyorum."],
      e: "**weil, dass, wenn** yan cümle kurar: **fiil sona gider** (*weil es mich **entspannt***). Türkçede fiil zaten sondadır, bu yüzden Almancada da sona atmak kolay gelir – asıl hata *weil es entspannt mich*. *Wenn* cümlesi 1. yeri doldurur; ana cümlenin fiili virgülden hemen sonra, 2. yerde gelir: *Wenn ich frei habe, **spiele** ich …*" }
  ]
});

/* ---------- Indirekte Fragen: ob, wo, wann … ---------- */
K.add('de-a2-16', {
  lesson: [
    { p: "Amtte, telefonda ya da doktorda doğrudan soru sormak yerine çoğu zaman **dolaylı soru** kullanırız: “*Ne zaman başladığını söyleyebilir misiniz?*” Türkçede bu yapı fiilin sonda olduğu bir ek-fiil yapısıdır (*-diğini, -ip -mediğini*). Almancada ise soru **yan cümleye** dönüşür ve **çekimli fiil sona** gider." },
    { table: { head: ["Doğrudan soru", "Dolaylı soru"], rows: [
      ["Wann beginnt der Kurs?", "Können Sie mir sagen, **wann** der Kurs **beginnt**?"],
      ["Wo ist das Büro?", "Wissen Sie, **wo** das Büro **ist**?"],
      ["Kommt er heute?", "Ich weiß nicht, **ob** er heute **kommt**."],
      ["Wie viel kostet das?", "Können Sie mir sagen, **wie viel** das **kostet**?"]
    ] } },
    { h: "1) İki kural" },
    { p: "**a) Soru sözcüğü varsa** (*wann, wo, wie, was, warum, wer, wie viel* …) aynı sözcük **bağlaç** olur: *Wann beginnt der Kurs?* → *… wann der Kurs **beginnt**.*" },
    { p: "**b) Soru sözcüğü yoksa** (evet/hayır sorusu) **ob** gelir: *Kommt er?* → *… **ob** er **kommt**.* **ob** Türkçedeki *-ip -mediğini / mi diye* gibidir." },
    { warn: "**ob** ile **soru sözcüğü** birlikte kullanılmaz: *ob wann …* ✗. **wenn** (eğer) ile **ob** da karışır: *Ich weiß nicht, wenn er kommt* ✗ → *Ich weiß nicht, **ob** er kommt* ✓. Fiil de sona gider: *ob kommt er* ✗." },
    { h: "2) Giriş kalıpları" },
    { table: { head: ["Kalıp", "Anlamı"], rows: [
      ["Können Sie mir sagen, …?", "Bana … söyleyebilir misiniz?"],
      ["Wissen Sie, …?", "… biliyor musunuz?"],
      ["Ich möchte wissen, …", "… bilmek istiyorum."],
      ["Ich weiß nicht, …", "… bilmiyorum."]
    ] } },
    { tip: "**Noktalama:** Cümlenin sonundaki işareti **ana cümle** belirler. Ana cümle soruysa soru işareti konur: *Können Sie mir sagen, wo das Büro ist?* Ana cümle bildirimse nokta konur: *Ich weiß nicht, wo das Büro ist.*" },
    { h: "3) Ayrılabilen fiil, modal fiil, Perfekt" },
    { p: "Kural *weil*’deki ile aynıdır. Ayrılabilen fiil **birleşir**: *Wissen Sie, wann der Zug **abfährt**?* Modal fiil sonda: *… wo ich unterschreiben **muss**?* Perfekt’te yardımcı fiil sonda: *… ob er schon angerufen **hat**.*" },
    { p: "**Neden kibar?** *Wo ist das Büro?* yanlış değildir ama doğrudan. *Können Sie mir sagen, wo das Büro ist?* aynı bilgiyi nazik, resmî bir tonda ister. Bu yüzden amirde, telefonda ve yabancılarla çok kullanılır." },
    { ex: [
      ["Können Sie mir sagen, wann das Bürgeramt öffnet?", "Bürgeramt’ın ne zaman açıldığını söyleyebilir misiniz?"],
      ["Wissen Sie, wo ich einen Termin bekomme?", "Nereden randevu alabileceğimi biliyor musunuz?"],
      ["Ich weiß nicht, ob er schon angerufen hat.", "Onun daha önce arayıp aramadığını bilmiyorum."],
      ["Ich möchte wissen, wie viel das kostet.", "Bunun ne kadar olduğunu öğrenmek istiyorum."],
      ["Können Sie mir sagen, ob am Freitag noch etwas frei ist?", "Cuma günü hâlâ boş yer olup olmadığını söyleyebilir misiniz?"]
    ] }
  ],
  exercises: [
    { id: "de-a2-16.1", t: "gap", q: "Können Sie mir sagen, ___ der Kurs beginnt? (ne zaman)", a: ["wann"],
      wrong: { "wenn": "*wenn* = eğer / her -dığında. “Ne zaman?” sorusu için **wann**.", "ob": "*ob* evet/hayır sorusu içindir. Burada soru sözcüğü (“ne zaman”) var → **wann**." },
      e: "Soru sözcüğü dolaylı soruda aynen kalır: *Wann beginnt der Kurs?* → *… **wann** der Kurs beginnt.*" },
    { id: "de-a2-16.2", t: "gap", q: "Ich weiß nicht, ___ er heute kommt. (gelip gelmediğini)", a: ["ob"],
      wrong: { "wenn": "*wenn* = eğer. “-ip -mediğini” anlamı için **ob** gerekir.", "dass": "*dass* bildirim içeriğini bağlar (*Ich weiß, dass er kommt*). Belirsizlik, evet/hayır → **ob**." },
      e: "Evet/hayır sorusu → **ob**: *Kommt er?* → *Ich weiß nicht, **ob** er kommt.*" },
    { id: "de-a2-16.3", t: "gap", q: "Wissen Sie, ___ das Bürgeramt ist? (nerede)", a: ["wo"],
      wrong: { "wohin": "*wohin* = nereye (hareket). “Nerede?” (yer) → **wo**.", "ob": "*ob* evet/hayır sorusu içindir; “nerede” bir soru sözcüğü: **wo**." },
      e: "*Wo ist das Bürgeramt?* → *Wissen Sie, **wo** das Bürgeramt **ist**?*" },
    { id: "de-a2-16.4", t: "gap", q: "Können Sie mir sagen, wie viel das ___? (kosten)", a: ["kostet"],
      wrong: { "kosten": "Özne *das* tekil (o, bu): das **kostet**. *kosten* çoğul (*die Schuhe kosten*) içindir.", "kostest": "*kostest* du içindir; özne *das* → **kostet**." },
      e: "Dolaylı soruda çekimli fiil en sonda: *wie viel das **kostet***." },
    { id: "de-a2-16.5", t: "gap", q: "Ich möchte wissen, ob der Zug pünktlich ___. (ankommen)", a: ["ankommt"],
      wrong: { "kommt an": "Ayrılabilen fiil yan cümlede **birleşir**: *ob der Zug pünktlich **ankommt***.", "ankommen": "Fiil özneye göre çekilir: der Zug **ankommt**." },
      e: "Dolaylı soru = yan cümle: *Kommt der Zug pünktlich an?* → *… ob der Zug pünktlich **ankommt**.*" },
    { id: "de-a2-16.6", t: "gap", q: "Können Sie mir sagen, wo ich unterschreiben ___? (müssen)", a: ["muss"],
      wrong: { "müssen": "Özne *ich* → ich **muss**. *müssen* wir/sie içindir.", "musst": "*musst* du içindir; ich → **muss**." },
      e: "Modal fiil sonda, mastar önünde: *wo ich unterschreiben **muss***." },
    { id: "de-a2-16.7", t: "gap", q: "Ich weiß nicht, ob er schon ___ hat. (anrufen)", a: ["angerufen"],
      wrong: { "anrufen": "*hat* ile Perfekt kurulur; **Partizip II** gerekir: **angerufen**.", "gerufen": "*anrufen* ayrılabilen fiildir; Partizip’te **an** + **ge** + **rufen**: *an**ge**rufen*." },
      e: "Perfekt: *Er hat angerufen.* Dolaylı soruda: *ob er schon **angerufen hat***." },
    { id: "de-a2-16.8", t: "mc", q: "“Wann beginnt der Kurs?” sorusunu dolaylı sor: “Können Sie mir sagen, …”", o: ["wann der Kurs beginnt?", "wann beginnt der Kurs?", "ob der Kurs beginnt wann?", "wann der beginnt Kurs?"], a: 0,
      why: { 1: "Doğrudan soru sırası; dolaylı soruda fiil **sona** gitmeli.", 2: "*ob* ile soru sözcüğü birlikte olmaz; üstelik *wann* sonda durmaz.", 3: "Fiil *beginnt* öznenin (*der Kurs*) **arkasında**, en sonda olmalı." },
      e: "**Soru sözcüğü + özne + … + fiil**: *wann der Kurs beginnt*." },
    { id: "de-a2-16.9", t: "mc", q: "“Kommt er heute?” sorusunu dolaylı sor: “Ich weiß nicht, …”", o: ["ob er heute kommt.", "wenn er heute kommt.", "ob kommt er heute.", "dass er heute kommt."], a: 0,
      why: { 1: "*wenn* = eğer. “… -ip -mediğini” → **ob**.", 2: "*ob* yan cümle kurar; fiil **sonda** olmalı: *ob er heute **kommt***.", 3: "*dass* = “-diğini”, belirsizlik/soru bildirmez. Evet/hayır sorusu için **ob**." },
      e: "Evet/hayır sorusu → **ob** + özne + … + fiil." },
    { id: "de-a2-16.10", t: "mc", q: "Hangi cümle **soru işareti** ile biter?", o: ["Ich weiß nicht, wo das Büro ist.", "Können Sie mir sagen, wo das Büro ist?", "Ich möchte wissen, wann der Kurs beginnt.", "Er fragt, ob ich Zeit habe."], a: 1,
      why: { 0: "Ana cümle *Ich weiß nicht* bildirim → nokta.", 2: "Ana cümle *Ich möchte wissen* bildirim → nokta.", 3: "Ana cümle *Er fragt* bildirim → nokta." },
      e: "Sonuna **ana cümle** karar verir: *Können Sie mir sagen …?* soru → **?**; *Ich weiß nicht …* bildirim → **.**" },
    { id: "de-a2-16.11", t: "mc", q: "Resmî bir telefon görüşmesinde Müller Hanım’ın nerede olduğunu nazikçe öğrenmek istiyorsun. Hangisi en uygun?", o: ["Können Sie mir bitte sagen, wo Frau Müller ist?", "Wo ist Frau Müller?", "Ich weiß nicht, wo Frau Müller ist.", "Wissen Sie, Frau Müller wo ist?"], a: 0,
      why: { 1: "Dil bilgisi olarak doğru ama **doğrudan** bir soru; resmî telefon için dolaylı soru daha nazik.", 2: "Bu bir **bildirim**: bilmiyorsun. Soru değil, rica da değil.", 3: "*Wissen Sie* sonrası yan cümle sırası yanlış: *wo Frau Müller **ist***." },
      e: "**Können Sie mir sagen, … ?** nazik bir kalıptır. Ardından yan cümle: *wo Frau Müller **ist***." },
    { id: "de-a2-16.12", t: "order", q: "Cümleyi kur: “Trenin ne zaman kalktığını söyleyebilir misiniz?”", w: ["Können", "Sie", "mir", "sagen", "wann", "der Zug", "abfährt"], a: ["Können Sie mir sagen wann der Zug abfährt"],
      e: "Ana cümle normal: *Können Sie mir sagen*, sonra yan cümle: *wann der Zug **abfährt***. *abfahren* yan cümlede birleşir." },
    { id: "de-a2-16.13", t: "order", q: "Cümleyi kur: “Onun bugün gelip gelmediğini bilmiyorum.”", w: ["Ich", "weiß", "nicht", "ob", "er", "heute", "kommt"], a: ["Ich weiß nicht ob er heute kommt"],
      e: "*ob* + özne + … + **çekimli fiil sonda**: *ob er heute **kommt***." },
    { id: "de-a2-16.14", t: "order", q: "Cümleyi kur: “Nereden randevu alabileceğimi biliyor musunuz?”", w: ["Wissen", "Sie", "wo", "ich", "einen Termin", "bekomme"], a: ["Wissen Sie wo ich einen Termin bekomme"],
      e: "*Wo bekomme ich einen Termin?* → *… wo ich einen Termin **bekomme***. Fiil sona gider." },
    { id: "de-a2-16.15", t: "match", q: "Doğrudan soruyu dolaylı soru ile eşleştir:", p: [["Wo ist die Toilette?", "Wissen Sie, wo die Toilette ist?"], ["Ist das Büro offen?", "Können Sie mir sagen, ob das Büro offen ist?"], ["Wann kommt der Bus?", "Ich möchte wissen, wann der Bus kommt."], ["Wie viel kostet das?", "Können Sie mir sagen, wie viel das kostet?"], ["Hat er Zeit?", "Ich weiß nicht, ob er Zeit hat."]],
      e: "Soru sözcüğü varsa aynen kalır, yoksa **ob** gelir; fiil her zaman sonda." },
    { id: "de-a2-16.16", t: "match", q: "Sözcüğü anlamıyla eşleştir:", p: [["wann", "ne zaman"], ["wo", "nerede"], ["wohin", "nereye"], ["woher", "nereden (geliş)"], ["ob", "-ip -mediğini / mi diye"]],
      e: "Hepsi dolaylı soruda bağlaç olur. **ob** ise soru sözcüğü olmayan, evet/hayır sorusu için kullanılır." },
    { id: "de-a2-16.17", t: "listen", say: "Können Sie mir bitte sagen, wo das Bürgeramt ist?", q: "Dinle. Kişi ne soruyor?", o: ["Bürgeramt’ın nerede olduğunu soruyor.", "Bürgeramt’ın açık olup olmadığını soruyor.", "Bürgeramt’ın ne zaman açıldığını soruyor.", "Bürgeramt’a nasıl gidileceğini bilmediğini söylüyor."], a: 0,
      why: { 1: "Açık olup olmadığını sormak için *ob das Büro offen ist* duyardın.", 2: "“Ne zaman” *wann* olurdu; duyduğun **wo** (nerede).", 3: "Bildirim yok, bir **soru** var: *Können Sie mir sagen …?*" },
      e: "*Können Sie mir bitte sagen, **wo** … ist?* = Bürgeramt’ın nerede olduğunu söyleyebilir misiniz? **wo** = nerede." },
    { id: "de-a2-16.18", t: "dictation", say: "Ich möchte wissen, ob der Kurs morgen beginnt.", a: ["Ich möchte wissen, ob der Kurs morgen beginnt."],
      wrong: { "Ich möchte wissen, ob beginnt der Kurs morgen": "*ob* yan cümle kurar; fiil **en sonda**: *ob der Kurs morgen **beginnt***.", "Ich möchte wissen, wenn der Kurs morgen beginnt": "*wenn* = eğer. “… -ip -mediğini” → **ob**." },
      e: "*möchte wissen* + **ob** + özne + … + fiil sonda. Cümle sonunda nokta: ana cümle bildirimdir." },
    { id: "de-a2-16.19", t: "speak", say: "Können Sie mir sagen, wann der Zug kommt?",
      e: "**Können**: ö = Türkçe ö, **nn** kısa. **sagen** = “zagen”: s sesli, g sert. **wann** = “van”. **Zug** = “tsuuk”: z = ts, u uzun, sondaki **g** “k” gibi okunur. Cümle sonunda ses yükselir: bu bir soru." },
    { id: "de-a2-16.20", t: "speak", say: "Ich weiß nicht, ob das Büro heute offen ist.",
      e: "**weiß** = “vays”: ß keskin s. **ob** = “op”: sondaki b “p” gibi okunur. **Büro** = “bü-ro”: ü Türkçe ü. **offen** = kısa o, f belirgin. Cümle düşerek biter: bildirim." },
    {"id":"de-a2-16.21","t":"cloze","q":"Soru sözcüğünü yaz.","text":"Weißt du, {1} die Post ist? Ich frage mich, {2} er morgen kommt – vielleicht hat er keine Zeit. Sag mir bitte, {3} du heute Abend kommst: um sieben oder um acht?","gaps":{"1":{"a":["wo"],"o":["wo","ob","wann"],"wrong":{"ob":"Yer soruluyor (nerede olduğu) → **wo**; *ob* evet/hayır sorusu içindir.","wann":"*wann* = ne zaman; yer soruluyor: **wo**."}},"2":{"a":["ob"],"o":["ob","wo","dass"],"wrong":{"wo":"Evet/hayır sorusu → **ob** (-mi).","dass":"*dass* haber verir, soru değil; evet/hayır sorusu için **ob**."}},"3":{"a":["wann"],"o":["wann","wo","ob"],"wrong":{"wo":"*wo* yer sorar; saat seçenekleri → **wann**.","ob":"*ob* evet/hayır sorusu; burada zaman soruluyor: **wann**."}}},"e":"Dolaylı soruda fiil **sona** gider. Evet/hayır sorusu → **ob**, W-sorusu → aynı soru sözcüğü (wo, wann, wie …). Önce virgül gelir."},
    {"id":"de-a2-16.22","t":"sort","q":"Dolaylı soruda ob mu, soru sözcüğü mü?","cats":["ob","W-Wort"],"items":[["Kommst du morgen?",0],["Wann kommst du?",1],["Hast du Zeit?",0],["Wo wohnst du?",1],["Ist der Zug pünktlich?",0],["Wie viel kostet das?",1]],"why":{"Kommst du morgen?":"Evet/hayır sorusu → *Ich frage, **ob** du kommst.*","Wann kommst du?":"Soru sözcüğü korunur → *Ich frage, **wann** du kommst.*","Hast du Zeit?":"Evet/hayır sorusu → **ob** du Zeit hast.","Wo wohnst du?":"Soru sözcüğü korunur → **wo** du wohnst.","Ist der Zug pünktlich?":"Evet/hayır sorusu → **ob** der Zug pünktlich ist.","Wie viel kostet das?":"Soru sözcüğü korunur → **wie viel** das kostet."},"e":"Doğrudan soruda fiil 1. sırada ise (*Kommst du?*) dolaylıda **ob** gelir. Soru sözcüğü varsa o aynen kalır; fiil sona gider."},
    {"id":"de-a2-16.23","t":"speak","say":"Ich weiß nicht, wann der Zug kommt.","e":"**weiß**: **ei** = “ay”, ß = “s”. **wann**: w = v, **nn** tek “n”. **Zug**: z = “ts”, “tsuuk”."},
    {"id":"de-a2-16.24","t":"speak","say":"Kannst du mir sagen, ob das Café offen ist?","e":"**Café** Fransızcadan: vurgu sonda, “kafe”. **offen**: o kısa (ff’den önce), **ob** = “op”, b sonda sert. Soru sonda yükselir."},
    { id: "de-a2-16.25", t: "respond", say: "Sie sind neu in der Stadt. Fragen Sie höflich nach dem Weg zum Bahnhof.",
      q: "Durumu dinle ve kibar bir yol sorusu sor. Dolaylı soru kullan.",
      chunks: ["Entschuldigung, können Sie mir sagen, …","Wissen Sie, wo …?","Können Sie mir sagen, ob …?","Vielen Dank!"],
      models: ["Entschuldigung, können Sie mir sagen, wo der Bahnhof ist?","Entschuldigung, wissen Sie, wie ich zum Bahnhof komme? Und können Sie mir sagen, ob der Bus dorthin fährt? Vielen Dank!"],
      modelsN: ["Affedersiniz, istasyonun nerede olduğunu söyleyebilir misiniz?","Affedersiniz, istasyona nasıl gideceğimi biliyor musunuz? Ve oraya otobüs gidiyor mu, söyleyebilir misiniz? Çok teşekkürler!"],
      e: "Kibar sorularda **dolaylı soru** kullanılır; fiil **sona** gider: *…, wo der Bahnhof **ist***. Düz soruda *Wo ist der Bahnhof?* fiil 2. sıradadır; dolaylı soruda ise ana cümle (*Können Sie mir sagen,*) + yan cümle gelir. *Evet/hayır* sorusunda **ob** gerekir: *…, ob der Bus **fährt***. Sık hata: *wissen Sie, wo ist der Bahnhof*. Araya virgül koymayı unutma." }
  ]
});

/* ---------- Konjunktiv II: höflich bitten & Rat geben ---------- */
K.add('de-a2-09', {
  lesson: [
    { p: "Türkçede nazik rica için “*-ebilir misiniz?, rica etsem, -mek isterdim*” gibi yumuşatıcı kalıplar kullanırız. Almancada bunun karşılığı **Konjunktiv II**’dir (nezaket ve gerçek dışı durum kipi; Türkçedeki *-ebilir miydiniz, -mek isterdim* gibi). A2’de bu kipi **sabit kalıplarla** öğreniyoruz; bütün fiilleri çekmene gerek yok. Sadece birkaç fiil yeter." },
    { h: "1) Altı önemli fiil" },
    { table: { head: ["", "ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], rows: [
      ["sein", "wäre", "wärst", "wäre", "wären", "wärt", "wären"],
      ["haben", "hätte", "hättest", "hätte", "hätten", "hättet", "hätten"],
      ["können", "könnte", "könntest", "könnte", "könnten", "könntet", "könnten"],
      ["werden", "würde", "würdest", "würde", "würden", "würdet", "würden"],
      ["sollen", "sollte", "solltest", "sollte", "sollten", "solltet", "sollten"],
      ["müssen", "müsste", "müsstest", "müsste", "müssten", "müsstet", "müssten"]
    ] } },
    { tip: "**ich** ve **er/sie/es** aynıdır (ek yok). **wir** ve **sie/Sie** ise **-n** ile biter. *könnte, müsste, würde, wäre, hätte* yazarken **ä / ö / ü** noktalarını unutma." },
    { h: "2) Nazik rica ve sipariş" },
    { p: "**Ich hätte gern …** = “… alabilir miyim / … rica ediyorum” (mağaza, kafe, restoran). **Könnten Sie …?** ve **Würden Sie bitte …?** = “… -ebilir misiniz?”. *Können Sie …?* de doğrudur ama daha doğrudandır; **Könnten** daha yumuşaktır. Fiil mastarı en sona gider: *Würden Sie bitte das Fenster **öffnen**?*" },
    { h: "3) İstek ve hayal: würde gern + mastar" },
    { p: "*Ich würde gern nach Italien fahren.* = İtalya’ya gitmek isterdim (şu an gidemesem de). **würde** 2. sırada, mastar **en sonda**." },
    { h: "4) Tavsiye: sollte ve „An deiner Stelle …“" },
    { p: "**Du solltest …** = “-sen iyi olur / yapmalısın” (yumuşak tavsiye). **An deiner Stelle würde ich …** = “Senin yerinde olsam …”. Karşılaştır: **Du musst …** = zorunluluk, **Du solltest …** = tavsiye. Almancada “senin yerinde” ile başlayan cümlede fiil yine 2. sıradadır: *An deiner Stelle **würde ich** zum Arzt gehen.*" },
    { h: "5) wäre ile teklif etmek" },
    { p: "*Wäre Dienstag um zehn Uhr in Ordnung?* = “Salı saat onda uygun olur mu?” (randevu için çok kullanılır). *Das wäre super.* = Bu harika olurdu. **müsste** ise “gitmem gerekirdi” gibi yumuşak bildirim yapar: *Ich müsste heute früher gehen.*" },
    { warn: "Hatalar: *Ich will einen Kaffee* ✗ (kibar değil, “istiyorum” gibi kesin ve kaba). → *Ich hätte gern einen Kaffee* ✓ ya da *Ich möchte …* ✓. *Du sollst zum Arzt gehen* (başkasının emri / zorunluluk) ile **Du solltest zum Arzt gehen** (tavsiye) farklıdır." },
    { ex: [
      ["Ich hätte gern einen Tee, bitte.", "Bir çay rica ediyorum."],
      ["Könnten Sie mir bitte helfen?", "Bana yardım edebilir misiniz?"],
      ["Du solltest mehr schlafen.", "Daha çok uyusan iyi olur."],
      ["An deiner Stelle würde ich zum Arzt gehen.", "Senin yerinde olsam doktora giderdim."],
      ["Wäre Montag um neun Uhr in Ordnung?", "Pazartesi saat dokuzda uygun olur mu?"]
    ] }
  ],
  exercises: [
    { id: "de-a2-09.1", t: "gap", q: "Ich ___ gern einen Kaffee, bitte. (nazik sipariş, haben)", a: ["hätte", "möchte"],
      wrong: { "habe": "*Ich habe gern einen Kaffee* “kahve içmeyi severim / elimde var” gibi anlaşılır, rica değil. Nazik sipariş için **hätte**.", "hatte": "*hatte* geçmiş zamandır (bende vardı). Rica için ä’lı **hätte**." },
      e: "**Ich hätte gern …** = nazik sipariş. *Ich möchte gern …* da aynı derecede nazik olduğu için kabul edilir." },
    { id: "de-a2-09.2", t: "gap", q: "___ Sie mir bitte helfen? (nazik rica, Konjunktiv II von können)", a: ["Könnten"],
      wrong: { "Können": "Dil bilgisi olarak doğru ama doğrudan bir sorudur; nazik rica için Konjunktiv II: **Könnten**.", "Könnte": "*Sie* ile çoğul biçim kullanılır: **Könnten Sie** (-n).", "Konnten": "*konnten* Präteritum’dur (yapabilirdiniz, geçmiş). Nazik rica için **ö** ve **-te-** ile: **Könnten**." },
      e: "**Könnten Sie …?** = “-ebilir misiniz?” (nazik). *Sie* ile fiil **-n** alır: könnten." },
    { id: "de-a2-09.3", t: "gap", q: "___ Sie bitte das Fenster öffnen? (nazik rica, werden)", a: ["Würden"],
      wrong: { "Würde": "*Sie* ile çoğul biçim: **Würden Sie**.", "Würdet": "*würdet* **ihr** içindir. *Sie* → **würden**.", "Werden": "*werden* geleceği bildirir (*Werden Sie kommen?*). Nazik rica için **Würden**." },
      e: "**Würden Sie bitte + mastar?** = nazik rica. Mastar (*öffnen*) en sonda." },
    { id: "de-a2-09.4", t: "gap", q: "Du ___ mehr schlafen. (tavsiye, sollen)", a: ["solltest"],
      wrong: { "sollst": "*sollst* Präsens’tir ve emir gibi durur (“yapman gerekiyor”). Yumuşak tavsiye: **solltest**.", "solltet": "*solltet* **ihr** içindir; *du* → **solltest**.", "sollte": "*sollte* ich ve er/sie/es içindir; *du* → **solltest**." },
      e: "**du solltest** = “-sen iyi olur”. **-st** eki *du*’ya aittir." },
    { id: "de-a2-09.5", t: "gap", q: "An deiner Stelle ___ ich zum Arzt gehen. (werden)", a: ["würde"],
      wrong: { "werde": "*werde* geleceği bildirir (“gideceğim”). “Senin yerinde olsam giderdim” → **würde**.", "wurde": "*wurde* (ü’süz) Präteritum’dur (oldu). Tavsiye için **würde**." },
      e: "**An deiner Stelle würde ich …** = “Senin yerinde olsam …”. Başta *An deiner Stelle* 1. yer, **würde** 2. sırada." },
    { id: "de-a2-09.6", t: "gap", q: "___ Dienstag um zehn Uhr in Ordnung? (nazik teklif, sein, Konjunktiv II)", a: ["Wäre"],
      wrong: { "Ist": "*Ist* de doğru bir sorudur ama doğrudandır. Nazik teklif için Konjunktiv II: **Wäre**.", "War": "*war* geçmiştir (idi). Teklif için **Wäre** (ä’lı)." },
      e: "**Wäre … möglich / in Ordnung?** = “… uygun olur mu?”. Randevu pazarlığında çok kullanılır." },
    { id: "de-a2-09.7", t: "gap", q: "Ich ___ gern nach Antalya fahren, aber ich habe keine Zeit. (werden)", a: ["würde"],
      wrong: { "werde": "*werde* = gideceğim (plan). “Gitmek isterdim” (gerçek olmayan istek) → **würde gern**.", "wurde": "*wurde* Präteritum’dur; **ü** ile **würde**." },
      e: "**würde gern + mastar** = “-mek isterdim”. Mastar (*fahren*) sonda." },
    { id: "de-a2-09.8", t: "mc", q: "Kafede nazikçe çorba sipariş etmek istiyorsun. Hangisi doğru?", o: ["Ich hätte gern eine Suppe.", "Ich will eine Suppe.", "Gib mir eine Suppe.", "Ich haben gern eine Suppe."], a: 0,
      why: { 1: "Dil bilgisi doğru ama *wollen* kaba ve kesin bir istek bildirir.", 2: "Emir kipi; arkadaşa söylenir, serviste kaba kaçar.", 3: "*ich* ile **habe** / **hätte**; *haben* wir/sie/Sie biçimidir." },
      e: "**Ich hätte gern …** = servis durumlarında nazik sipariş." },
    { id: "de-a2-09.9", t: "mc", q: "“Doktora gitsen iyi olur.” (arkadaşına tavsiye) Hangisi doğru?", o: ["Du solltest zum Arzt gehen.", "Du sollst zum Arzt gehen.", "Du solltest zum Arzt gehst.", "Du sollte zum Arzt gehen."], a: 0,
      why: { 1: "*sollst* emir veya “gitmen isteniyor” gibi duyulur; tavsiye için Konjunktiv II.", 2: "*solltest* yanında fiil **mastar** olur (*gehen*), çekilmez.", 3: "*du* ile **solltest** (-st)." },
      e: "**du solltest + mastar** = yumuşak tavsiye." },
    { id: "de-a2-09.10", t: "mc", q: "Hangisi pencereyi açmak için **en nazik** rica?", o: ["Mach das Fenster auf!", "Machen Sie das Fenster auf!", "Würden Sie bitte das Fenster aufmachen?", "Sie machen das Fenster auf."], a: 2,
      why: { 0: "Emir kipi; sadece yakınlara söylenir ve sert gelebilir.", 1: "*Sie* ile emir de saygılıdır ama yine **emirdir**; rica değil.", 3: "Bildirim cümlesi; rica değil, “açıyorsunuz” gibi duyulur." },
      e: "**Würden Sie bitte + mastar?** nazik bir rica kalıbı." },
    { id: "de-a2-09.11", t: "mc", q: "*An deiner Stelle würde ich zum Arzt gehen.* ne demek?", o: ["Senin yerinde olsam doktora giderdim.", "Senin yerine doktora gideceğim.", "Senin evinde doktora gidiyorum.", "Doktor senin yerinde duruyor."], a: 0,
      why: { 1: "Başkası adına gitmekten söz edilmiyor; *an deiner Stelle* = senin yerinde (olsam).", 2: "*Stelle* = yer/konum, ev değil.", 3: "Cümlede doktorun yeri anlatılmıyor; bu bir tavsiye kalıbı." },
      e: "**An deiner Stelle würde ich …** = kendini karşındakinin yerine koyup tavsiye vermek." },
    { id: "de-a2-09.12", t: "order", q: "Cümleyi kur: “Bana yardım edebilir misiniz?”", w: ["Könnten", "Sie", "mir", "bitte", "helfen"], a: ["Könnten Sie mir bitte helfen"],
      e: "*Könnten Sie mir bitte helfen?* Fiil 1. sırada (soru), mastar **en sonda**." },
    { id: "de-a2-09.13", t: "order", q: "Cümleyi kur: “Senin yerinde olsam daha çok uyurdum.”", w: ["An deiner Stelle", "würde", "ich", "mehr", "schlafen"], a: ["An deiner Stelle würde ich mehr schlafen", "Ich würde an deiner Stelle mehr schlafen"],
      e: "*An deiner Stelle* 1. yer → **würde ich** (fiil + özne). Mastar *schlafen* sonda. Diğer sıra da doğru." },
    { id: "de-a2-09.14", t: "order", q: "Cümleyi kur: “İki kişilik bir masa rica ediyorum.”", w: ["Ich", "hätte", "gern", "einen Tisch", "für zwei Personen"], a: ["Ich hätte gern einen Tisch für zwei Personen"],
      e: "**Ich hätte gern + Akkusativ**: *einen Tisch* (der Tisch → Akkusativ: einen)." },
    { id: "de-a2-09.15", t: "match", q: "Kalıbı anlamıyla eşleştir:", p: [["Ich hätte gern …", "… rica ediyorum"], ["Könnten Sie …?", "… -ebilir misiniz?"], ["Du solltest …", "… -sen iyi olur"], ["Ich würde gern …", "… -mek isterdim"], ["Wäre … möglich?", "… mümkün olur mu?"]],
      e: "Beş kalıbı ezberlemek A2 için yeterlidir. Hepsi **Konjunktiv II**’dir." },
    { id: "de-a2-09.16", t: "match", q: "Durumu uygun cümle ile eşleştir:", p: [["Kafede sipariş veriyorsun.", "Ich hätte gern einen Tee."], ["Arkadaşının sırtı ağrıyor.", "Du solltest einen Termin machen."], ["Resmî dairede yardım istiyorsun.", "Könnten Sie mir bitte helfen?"], ["Tatilde denize gitmek istiyorsun.", "Ich würde gern ans Meer fahren."], ["Randevu için gün öneriyorsun.", "Wäre Montag um neun Uhr in Ordnung?"]],
      e: "Her kalıp bir duruma bağlı: servis → **hätte gern**, tavsiye → **solltest**, rica → **Könnten Sie**, istek → **würde gern**, teklif → **Wäre …**." },
    { id: "de-a2-09.17", t: "listen", say: "Hätten Sie am Freitag einen Termin für mich?", q: "Dinle. Ne anlama geliyor?", o: ["Cuma günü bana bir randevunuz var mı?", "Cuma günü randevum vardı.", "Cuma günü randevu aldım.", "Cuma günü randevuya geliyorum."], a: 0,
      why: { 1: "Geçmiş zaman (*hatte*) duymadın; **Hätten Sie** bir **soru** ve rica.", 2: "“Randevu aldım” *Ich habe einen Termin bekommen* olurdu; burada soru var.", 3: "“Geliyorum” bildirimdir; duyduğun soru: *Hätten Sie …?*" },
      e: "**Hätten Sie … einen Termin?** = “… randevunuz var mı?” (nazik sorma). *am Freitag* = cuma günü." },
    { id: "de-a2-09.18", t: "dictation", say: "An deiner Stelle würde ich zum Arzt gehen.", a: ["An deiner Stelle würde ich zum Arzt gehen."],
      wrong: { "An deiner Stelle werde ich zum Arzt gehen": "*werde* gelecektir; tavsiye için Konjunktiv II: **würde**.", "An deiner Stelle ich würde zum Arzt gehen": "*An deiner Stelle* 1. yerdedir; fiil hemen arkasından gelir: *würde ich*.", "An deiner Stelle wurde ich zum Arzt gehen": "**ü** noktaları eksik: *w**ü**rde*." },
      e: "**An deiner Stelle** (1. yer) + **würde ich** (fiil + özne) + **zum Arzt gehen** (mastar sonda)." },
    { id: "de-a2-09.19", t: "speak", say: "Ich hätte gern einen Kaffee, bitte.",
      e: "**hätte**: ä = Türkçe e (“hete”), h net duyulur, tt kısa. **gern**: g sert, r hafif. **Kaffee** = “KA-fe”: vurgu ilk hecede, son e kısa. Nazik ama düz bir tonla söyle; *bitte* yumuşak." },
    { id: "de-a2-09.20", t: "speak", say: "Könnten Sie mir bitte helfen?",
      e: "**Könnten**: ö = Türkçe ö, **nn** kısa; vurgu ilk hecede. **bitte** = “bite”: **tt** kısa. **helfen**: h nefes gibi, **lf** birleşik. Soru: sonda ses yükselir." },
    {"id":"de-a2-09.21","t":"cloze","q":"Kibar (Konjunktiv II) biçimi yaz.","text":"Ich {1} gern einen Tee (haben). {2} Sie mir bitte helfen? Du {3} (sollen) mehr schlafen.","gaps":{"1":{"a":["hätte"],"o":["hätte","habe","hatte"],"wrong":{"habe":"*Ich habe gern* = sahip olmayı severim; rica değil. Kibar istek: **hätte gern**.","hatte":"*hatte* Präteritum’dur (vardı); kibar rica için umlaut’lu **hätte**."}},"2":{"a":["Könnten"],"o":["Könnten","Können","Konnten"],"wrong":{"Können":"*Können Sie …?* dilbilgisi olarak doğru, ama burada kibar Konjunktiv II istendi: **Könnten**.","Konnten":"*konnten* Präteritum’dur; **ö** (Könnten) kibar rica yapar."}},"3":{"a":["solltest"],"wrong":{"sollst":"*du sollst* emir gibi duyulur; tavsiye için **solltest**.","sollte":"*du* ile -st gelir: **solltest**."}}},"e":"**hätte** gern + isim (*Ich hätte gern einen Tee*) kibar bir istektir. **könnte, sollte, würde** + mastar = kibar rica ve tavsiye. Türkçede “… alabilir miyim?”, “… yapsan iyi olur” gibi."},
    {"id":"de-a2-09.22","t":"sort","q":"Rica mı, tavsiye mi?","cats":["höfliche Bitte","Rat geben"],"items":[["Könnten Sie mir helfen?",0],["Du solltest mehr Wasser trinken.",1],["Hätten Sie einen Moment Zeit?",0],["An deiner Stelle würde ich mehr schlafen.",1],["Würden Sie bitte das Fenster schließen?",0],["Du solltest früher ins Bett gehen.",1]],"why":{"Könnten Sie mir helfen?":"Karşı taraftan bir şey istiyorsun → rica.","Du solltest mehr Wasser trinken.":"Tavsiye: *du solltest* = sen şunu yapsan iyi olur.","Hätten Sie einen Moment Zeit?":"Kibar rica: bir an vakti var mı?","An deiner Stelle würde ich mehr schlafen.":"Tavsiye: “senin yerinde olsam …”.","Würden Sie bitte das Fenster schließen?":"Kibar rica (würden + mastar).","Du solltest früher ins Bett gehen.":"Tavsiye: *solltest*."},"e":"Rica: **Könnten/Würden/Hätten Sie …?** Tavsiye: **Du solltest …** veya **An deiner Stelle würde ich …**."},
    {"id":"de-a2-09.23","t":"speak","say":"Könnten Sie das bitte wiederholen?","e":"**Könnten**: **ö** Türkçe ö gibi, **nn** kısa. **wiederholen**: vurgu **ho** hecesinde: vii-der-**HOO**-len. Rica soruları sonda hafif yükselir."},
    { id: "de-a2-09.24", t: "respond", say: "Was würdest du mit viel Geld machen? Was möchtest du gern lernen?",
      q: "Soruyu dinle ve 2–3 cümleyle cevap ver. würde ve möchte kullan.",
      chunks: ["Ich würde …","Ich möchte gern …","Dann könnte ich …","Wenn ich Zeit hätte, …"],
      models: ["Ich würde eine Reise machen. Ich möchte gern besser Deutsch sprechen.","Mit viel Geld würde ich ein kleines Haus kaufen. Dann könnte ich einen Garten haben. Wenn ich Zeit hätte, würde ich auch gern Klavier lernen."],
      modelsN: ["Bir seyahate çıkardım. Daha iyi Almanca konuşmak isterim.","Çok param olsa küçük bir ev alırdım. O zaman bir bahçem olabilirdi. Vaktim olsa piyano da öğrenmek isterdim."],
      e: "**würde + Infinitiv** hayalî/koşullu durumu anlatır: *Ich **würde** eine Reise **machen*** (Infinitiv en sonda). Türkçedeki *-ırdım/-erdim* karşılığıdır. **möchte** nazik istek: *Ich möchte gern …* – *Ich will* biraz sert durur. Sık hata: *Ich würde machen eine Reise*. *hätte, könnte, wäre* sık kullanılan kısa Konjunktiv-II biçimleridir." }
  ]
});

